import 'package:flutter/material.dart';
import 'package:showcaseview/showcaseview.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: ShowCaseWidget(
        builder: Builder(
          builder: (context) => const HomePage(),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:showcaseview/showcaseview.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  final GlobalKey _keyMenu = GlobalKey();
  final GlobalKey _keySearch = GlobalKey();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Showcase Demo')),
      body: Column(
        children: [
          Showcase(
            key: _keyMenu,
            description: '여기에서 메뉴를 열 수 있어요',
            child: IconButton(
              icon: const Icon(Icons.menu),
              onPressed: () {},
            ),
          ),
          Showcase(
            key: _keySearch,
            description: '검색 기능을 사용할 수 있어요',
            child: const TextField(decoration: InputDecoration(hintText: '검색')),
          ),
        ],
      ),
    );
  }
}
